SELECT tenant_id,project_id,artifact_id,artifact_kind,object_ref,object_key,object_version,sha256,size_bytes,media_type,
       dependency_access_set_id,content_sha256,schema_version,schema_manifest_sha256,classification
FROM artifact a WHERE artifact_id=#{id}

SELECT write_id FROM formal_evaluation_runtime_object_intent WHERE artifact_id=#{artifactId}
UNION ALL SELECT write_id FROM formal_evaluation_deterministic_object_intent WHERE artifact_id=#{artifactId}
UNION ALL SELECT write_id FROM formal_evaluation_stage_input_intent WHERE artifact_id=#{artifactId}
